-- ========================================================================
-- BEGIN 07_create_table_mammography_test_result_grade_flag.sql
-- ========================================================================

-- Safety-critical flags for a mammography result, independent of the axes.

CREATE TABLE mammography_test_result_grade_flag (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    mammography_test_result_grade_id UUID NOT NULL
        REFERENCES mammography_test_result_grade(id) ON DELETE CASCADE,
    flag_id VARCHAR(50) NOT NULL,
    category VARCHAR(40) NOT NULL DEFAULT ''
        CHECK (category IN (
            'critical-result-alert',
            'incidental-finding',
            'discrepancy-with-request',
            'abnormal-requiring-action',
            'urgent-referral',
            'inadequate-technique',
            'unexpected-finding',
            'missing-impression',
            'missing-measurement',
            'other',
            ''
        )),
    priority VARCHAR(10) NOT NULL DEFAULT ''
        CHECK (priority IN ('low', 'medium', 'high', '')),
    description VARCHAR(500) NOT NULL DEFAULT '',
    suggested_action VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX index_mammography_test_result_grade_flag_grade_id
    ON mammography_test_result_grade_flag(mammography_test_result_grade_id);

CREATE TRIGGER trigger_mammography_test_result_grade_flag_updated_at
    BEFORE UPDATE ON mammography_test_result_grade_flag
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE mammography_test_result_grade_flag IS
    'Safety-critical flags that fire independently of the four axes, with priority and a suggested action for the reporting / referring team. A BI-RADS 4 or 5 final assessment raises abnormal-requiring-action and urgent-referral flags.';
COMMENT ON COLUMN mammography_test_result_grade_flag.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN mammography_test_result_grade_flag.created_at IS
    'Timestamp when this row was created.';
COMMENT ON COLUMN mammography_test_result_grade_flag.updated_at IS
    'Timestamp when the record was updated most-recently.';
COMMENT ON COLUMN mammography_test_result_grade_flag.deleted_at IS
    'Timestamp when the record was deleted a.k.a. soft-removed.';
COMMENT ON COLUMN mammography_test_result_grade_flag.mammography_test_result_grade_id IS
    'Foreign key to the parent grade.';
COMMENT ON COLUMN mammography_test_result_grade_flag.flag_id IS
    'Stable flag identifier (e.g. F-URGENT-REFERRAL-001).';
COMMENT ON COLUMN mammography_test_result_grade_flag.category IS
    'Flag category.';
COMMENT ON COLUMN mammography_test_result_grade_flag.priority IS
    'Priority: low, medium, high.';
COMMENT ON COLUMN mammography_test_result_grade_flag.description IS
    'Human-readable description of what fired the flag.';
COMMENT ON COLUMN mammography_test_result_grade_flag.suggested_action IS
    'Suggested clinical action (e.g. "refer for image-guided biopsy and communicate to breast MDT").';

-- ========================================================================
-- END 07_create_table_mammography_test_result_grade_flag.sql
-- ========================================================================
